// frontend/src/utils/numbers.js
// ============================================================
//  🔢 Utility functions — اعداد و تاریخ‌های فارسی
//
//  استفاده:
//    import { toFa, toFaShort, toFaDate, toFaTimeAgo } from '../../utils/numbers';
//    <span className="font-num">{toFa(1500)}</span>
//
//  برای اینپوت‌ها:
//    import { toFaDigits, toEnDigits, toNumber } from '../utils/numbers';
//    value={form.weight_kg}                            // در حین تایپ: toFaDigits
//    weight_kg: toNumber(form.weight_kg)               // قبل از ارسال به API
// ============================================================

// ============================================================
//  🔒 Internal helpers
// ============================================================

const PERSIAN_DIGITS = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
const ARABIC_DIGITS  = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];

/**
 * تبدیل ارقام انگلیسی به فارسی (بدون تغییر ساختار)
 */
const toPersianDigits = (str) =>
  String(str ?? '').replace(/[0-9]/g, (d) => PERSIAN_DIGITS[Number(d)]);

/**
 * بررسی اعتبار Date
 * - new Date('hello') استثنا پرتاب نمی‌کنه ولی Invalid Date برمی‌گردونه
 * - پس try/catch کافی نیست
 */
const isValidDate = (d) => d instanceof Date && !Number.isNaN(d.getTime());

/**
 * ساخت Date از ورودی مختلف (Date | ISO string | timestamp)
 * ✅ FIX: برای Date هم اعتبار چک می‌شود تا Invalid Date عبور نکند.
 */
const safeDate = (input) => {
  if (!input) return null;
  if (input instanceof Date) return isValidDate(input) ? input : null;
  try {
    const d = new Date(input);
    return isValidDate(d) ? d : null;
  } catch {
    return null;
  }
};

// ============================================================
//  🔄 تبدیل ارقام (برای اینپوت‌ها)
// ============================================================

/**
 * تبدیل ارقام انگلیسی/عربی → فارسی
 * برای استفاده در onChange اینپوت‌ها (نمایش فارسی حین تایپ)
 * @param {string|number} str
 * @returns {string} - مثلاً: "12.5" → "۱۲٫۵"  (نقطه به ممیز فارسی تبدیل نمی‌شود مگر با toFaNumberInput)
 */
export const toFaDigits = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/[0-9]/g, (d) => PERSIAN_DIGITS[Number(d)])
    .replace(/[٠-٩]/g, (d) => PERSIAN_DIGITS[ARABIC_DIGITS.indexOf(d)]);
};

/**
 * نسخهٔ کامل برای اینپوت‌های عددی — علاوه بر ارقام،
 * نقطه و ویرگول اعشار را هم به ممیز فارسی (٫) تبدیل می‌کند.
 * @param {string|number} str
 * @returns {string}
 */
export const toFaNumberInput = (str) => {
  if (str === null || str === undefined) return '';
  return toFaDigits(str).replace(/[.,]/g, '٫');
};

/**
 * تبدیل ارقام فارسی/عربی → انگلیسی
 * برای ارسال به بک‌اند، Number()، JSON، localStorage و...
 * @param {string|number} str
 * @returns {string}
 */
export const toEnDigits = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/[۰-۹]/g, (d) => String(PERSIAN_DIGITS.indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String(ARABIC_DIGITS.indexOf(d)))
    .replace(/٫/g, '.')   // ممیز فارسی/عربی → نقطه
    .replace(/٬/g, '');   // جداکنندهٔ هزارگان فارسی → حذف
};

/**
 * تبدیل امن هر ورودی (فارسی/عربی/انگلیسی) به عدد JS
 * هرگز NaN برنمی‌گرداند — در صورت خطا، fallback را برمی‌گرداند.
 * @param {string|number} str
 * @param {number} fallback
 * @returns {number}
 */
export const toNumber = (str, fallback = 0) => {
  if (str === null || str === undefined || str === '') return fallback;
  const num = Number(toEnDigits(str).trim());
  return Number.isNaN(num) ? fallback : num;
};

// ============================================================
//  🔢 فرمت اعداد
// ============================================================

/**
 * تبدیل هر عددی به فرمت فارسی با جداکننده هزارگان
 * @param {number|string} n - عدد ورودی
 * @param {string} fallback - مقدار پیش‌فرض در صورت نامعتبر بودن (پیش‌فرض '—')
 * @returns {string} - عدد فارسی (مثلاً: ۱٬۵۰۰)
 */
export const toFa = (n, fallback = '—') => {
  if (n === null || n === undefined || n === '') return fallback;
  const num = Number(n);
  if (Number.isNaN(num)) return fallback;
  return num.toLocaleString('fa-IR');
};

/**
 * فرمت کوتاه‌شده عدد (هزار / میلیون / میلیارد)
 * ✅ FIX: استفاده از toLocaleString با useGrouping:false — بدون باگ حذف صفرهای صحیح
 * @param {number|string} n
 * @param {string} fallback
 * @returns {string} - مثلاً: «۱٫۵ میلیون» یا «۱۰ هزار»
 */
export const toFaShort = (n, fallback = '—') => {
  if (n === null || n === undefined || n === '') return fallback;
  const num = Number(n);
  if (Number.isNaN(num)) return fallback;

  const abs = Math.abs(num);
  const sign = num < 0 ? '-' : '';

  // ✅ FIX: بدون useGrouping و trim دستی — فقط به‌اندازهٔ لازم رقم اعشار
  const shortNum = (value, decimals) =>
    value.toLocaleString('fa-IR', {
      minimumFractionDigits: 0,
      maximumFractionDigits: decimals,
      useGrouping: false,
    });

  if (abs >= 1_000_000_000) {
    return `${sign}${shortNum(abs / 1_000_000_000, 1)} میلیارد`;
  }
  if (abs >= 1_000_000) {
    return `${sign}${shortNum(abs / 1_000_000, 1)} میلیون`;
  }
  if (abs >= 1_000) {
    return `${sign}${shortNum(abs / 1_000, 0)} هزار`;
  }
  return num.toLocaleString('fa-IR');
};

/**
 * تبدیل عدد اعشاری به فارسی با تعداد رقم اعشار مشخص
 * @param {number|string} n
 * @param {number} digits - تعداد رقم اعشار (پیش‌فرض ۱)
 * @param {string} fallback
 * @returns {string} - مثلاً: ۱۴٫۵
 */
export const toFaDecimal = (n, digits = 1, fallback = '—') => {
  if (n === null || n === undefined || n === '') return fallback;
  const num = Number(n);
  if (Number.isNaN(num)) return fallback;
  return num.toLocaleString('fa-IR', {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  });
};

/**
 * فرمت قیمت به فارسی + جداکننده هزارگان
 * @param {number|string} n
 * @param {boolean} withToman - آیا "تومان" اضافه شود؟ (پیش‌فرض false)
 */
export const toFaPrice = (n, withToman = false) => {
  const formatted = toFa(n, '۰');
  return withToman ? `${formatted} تومان` : formatted;
};

/**
 * فرمت وزن به فارسی + "گرم" یا "کیلوگرم"
 * ✅ FIX: حذف محاسبهٔ اضافه (toFixed سپس re-parse)
 * @param {number|string} grams
 * @returns {string} - مثلاً: ۹۱۹ گرم یا ۱٫۵۰ کیلوگرم
 */
export const toFaWeight = (grams) => {
  if (grams === null || grams === undefined || grams === '') return '—';
  const g = Number(grams);
  if (Number.isNaN(g)) return '—';

  if (g >= 1000) {
    return `${toFaDecimal(g / 1000, 2)} کیلوگرم`;
  }
  return `${toFa(g)} گرم`;
};

/**
 * تبدیل ارقام به فارسی — بدون جداکننده (مثل شمارهٔ سفارش، کد رهگیری)
 * @param {number|string} n
 * @returns {string} - مثلاً: 1500 → ۱۵۰۰
 */
export const toFaRaw = (n) => {
  if (n === null || n === undefined || n === '') return '';
  return toPersianDigits(n);
};

/**
 * فرمت درصد به فارسی — بدون جداکنندهٔ هزارگان
 * (چون درصد معمولاً عدد کوچیکه: ۴۵٪، نه ۱٬۰۰۰٪)
 * @param {number|string} n
 * @returns {string} - مثلاً: ۴۵٪
 */
export const toFaPercent = (n) => {
  if (n === null || n === undefined || n === '') return '۰٪';
  const num = Number(n);
  if (Number.isNaN(num)) return '۰٪';
  return `${toFaRaw(Math.round(num))}٪`;
};

/**
 * فرمت اندازهٔ فایل به فارسی
 * @param {number} bytes
 * @returns {string} - مثلاً: ۴۵۰ KB یا ۱٫۵ MB
 */
export const toFaFileSize = (bytes) => {
  if (bytes === null || bytes === undefined || Number.isNaN(Number(bytes))) {
    return '۰ KB';
  }
  const b = Number(bytes);
  if (b < 0) return '۰ KB';
  if (b < 1024) return `${toFa(Math.round(b))} B`;
  if (b < 1024 * 1024) return `${toFa(Math.round(b / 1024))} KB`;
  return `${toFaDecimal(b / 1024 / 1024, 1)} MB`;
};

// ============================================================
//  📅 فرمت تاریخ و ساعت
// ============================================================

/**
 * فرمت تاریخ به فارسی
 * @param {string|Date} dateOrIso
 * @param {object} options - اختیارات toLocaleDateString
 * @param {string} fallback
 * @returns {string} - مثلاً: ۱۵ آبان ۱۴۰۳
 */
export const toFaDate = (
  dateOrIso,
  options = { year: 'numeric', month: 'long', day: 'numeric' },
  fallback = '—'
) => {
  const d = safeDate(dateOrIso);
  if (!d) return fallback;
  return d.toLocaleDateString('fa-IR', options);
};

/**
 * فرمت تاریخ کامل فارسی (با نام روز هفته)
 * @returns {string} - مثلاً: دوشنبه ۱۵ آبان ۱۴۰۳
 */
export const toFaDateFull = (dateOrIso, fallback = '—') => {
  const d = safeDate(dateOrIso);
  if (!d) return fallback;
  return d.toLocaleDateString('fa-IR', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
};

/**
 * فرمت ساعت به فارسی
 * @returns {string} - مثلاً: ۱۴:۳۰ یا ۱۴:۳۰:۲۵
 */
export const toFaTime = (
  dateOrIso,
  options = { hour: '2-digit', minute: '2-digit' },
  fallback = '—'
) => {
  const d = safeDate(dateOrIso);
  if (!d) return fallback;
  return d.toLocaleTimeString('fa-IR', options);
};

/**
 * فرمت تاریخ و ساعت با هم
 * @returns {string} - مثلاً: ۱۵ آبان، ۱۴:۳۰
 */
export const toFaDateTime = (dateOrIso, options = {}, fallback = '—') => {
  const d = safeDate(dateOrIso);
  if (!d) return fallback;
  const defaultOptions = {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  };
  return d.toLocaleString('fa-IR', { ...defaultOptions, ...options });
};

/**
 * زمان نسبی (چند دقیقه پیش، چند ساعت پیش و...)
 * @returns {string} - مثلاً: «۲ ساعت پیش» یا «۳ روز پیش»
 */
export const toFaTimeAgo = (dateOrIso, fallback = '—') => {
  const d = safeDate(dateOrIso);
  if (!d) return fallback;

  const diff = Date.now() - d.getTime();

  if (diff < 0) return 'در آینده';

  const mins = Math.floor(diff / 60000);
  const hours = Math.floor(diff / 3600000);
  const days = Math.floor(diff / 86400000);

  if (mins < 1) return 'همین الان';
  if (mins < 60) return `${toFa(mins)} دقیقه پیش`;
  if (hours < 24) return `${toFa(hours)} ساعت پیش`;
  if (days < 30) return `${toFa(days)} روز پیش`;
  return d.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });
};

// ============================================================
//  📦 Export پیش‌فرض
// ============================================================
export default {
  // تبدیل ارقام (برای اینپوت‌ها و API)
  toFaDigits,
  toFaNumberInput,
  toEnDigits,
  toNumber,
  // اعداد
  toFa,
  toFaShort,
  toFaDecimal,
  toFaPrice,
  toFaWeight,
  toFaRaw,
  toFaPercent,
  toFaFileSize,
  // تاریخ و ساعت
  toFaDate,
  toFaDateFull,
  toFaTime,
  toFaDateTime,
  toFaTimeAgo,
};