// frontend/src/user/components/SiteFooter.jsx
// ============================================================
//  🐾 SiteFooter v17 — Miko Warm & Friendly
//  ✅ v17:
//  - شماره موبایل هاردکد با اعداد فارسی (بدون toFa)
//  - حذف کامل واتساپ
//  - کاهش عرض فوتر (max-w-5xl)
//  - حس دوستانه‌تر: گرادیانت نوار بالا، سایه نرم‌تر، هاور لینک‌ها
//  - رفع مشکل نمایش شماره موبایل (tracking و dir)
// ============================================================

import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { toFaDate } from '../../utils/numbers';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  📞 ثابت‌های تماس (نمایش فارسی + لینک تماس)
// ============================================================
const PHONE_DISPLAY = '۰۹۱۲۰۵۱۵۶۵۹';
const PHONE_HREF = 'tel:+989120515659';

// ============================================================
//  🌐 آیکون‌های SVG (Fallback برای SiteImage)
// ============================================================
const InstagramIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-full h-full">
    <rect x="2" y="2" width="20" height="20" rx="5" ry="5" />
    <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z" />
    <line x1="17.5" y1="6.5" x2="17.51" y2="6.5" />
  </svg>
);

const TelegramIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full">
    <path d="M9.04 15.51l-.39 5.5c.56 0 .8-.24 1.09-.52l2.62-2.5 5.42 3.97c.99.55 1.7.26 1.96-.92L22.9 4.55c.32-1.47-.53-2.04-1.5-1.67L2.28 9.93c-1.42.56-1.4 1.35-.24 1.71l4.9 1.53 11.34-7.16c.53-.35 1.02-.16.62.19l-9.86 9.31z" />
  </svg>
);

const PhoneIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-full h-full">
    <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z" />
  </svg>
);

// ============================================================
//  📋 داده‌ها
// ============================================================
const QUICK_LINKS = [
  { label: 'صفحه اصلی', href: '/' },
  { label: 'محاسبه رژیم', href: '/#quick-calculator' },
  { label: 'چرا میکو؟', href: '/#benefits' },
  { label: 'سؤالات متداول', href: '/#faq' },
];

const SUPPORT_LINKS = [
  { label: 'پنل کاربری', href: '/panel' },
  { label: 'پیگیری سفارش', href: '/panel/orders' },
  { label: 'ارسال تیکت', href: '/panel/tickets/new' },
  { label: 'ثبت نظر', href: '/panel/testimonials/new' },
];

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function SiteFooter() {
  const location = useLocation();
  const persianYear = toFaDate(new Date(), { year: 'numeric' }, '');

  const handleNavClick = (e, href) => {
    if (href === '/') {
      if (location.pathname === '/') {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } else if (href.startsWith('/#')) {
      const id = href.replace('/#', '');
      const el = document.getElementById(id);
      if (el) {
        e.preventDefault();
        const top = el.getBoundingClientRect().top + window.pageYOffset - 80;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }
  };

  return (
    <footer className="relative bg-miko-rust pt-10 pb-6 sm:pt-14 sm:pb-8" role="contentinfo">
      <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8">
        {/* کارت کرم رنگ فوتر */}
        <div className="overflow-hidden rounded-2xl bg-miko-cream shadow-xl sm:rounded-[2rem]">
          {/* گرادیانت نوار بالا برای حس دوستانه‌تر */}
          <div className="h-1.5 w-full bg-gradient-to-r from-miko-rust via-miko-pumpkin to-miko-carrot" />

          <div className="p-6 sm:p-8 lg:p-9">
            <div className="grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-6">

              {/* ۱. برند (۵ ستون) */}
              <div className="md:col-span-5 flex flex-col items-start">
                <Link
                  to="/"
                  onClick={(e) => handleNavClick(e, '/')}
                  className="flex items-center gap-3 group mb-4"
                >
                  <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-miko-rust shadow-sm overflow-hidden p-1.5 transition-transform group-hover:scale-105 group-hover:-rotate-3">
                    <SiteImage
                      imageKey="footer_logo"
                      fallback=""
                      alt="لوگوی میکو"
                      className="w-full h-full object-contain"
                      placeholderContent={<span className="font-miko text-2xl text-miko-cream">م</span>}
                      showPlaceholder={true}
                    />
                  </div>
                  <div>
                    <div className="font-miko text-3xl leading-none text-miko-rust">میکو</div>
                    <div className="text-[10px] font-black tracking-[0.2em] text-miko-olive mt-1">
                      SMALL BATCH · BABOL
                    </div>
                  </div>
                </Link>
                <p className="text-[13px] sm:text-sm font-semibold text-miko-dark/80 leading-7 max-w-[280px]">
                  غذای خانگی تازه و اختصاصی برای سلامت و شادی رفیق پشمالوی شما. 🐾
                </p>

                {/* شبکه‌های اجتماعی — فقط اینستاگرام و تلگرام */}
                <div className="mt-5 flex items-center gap-3">
                  <a
                    href="https://instagram.com/mico.dogfood"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="group flex h-10 w-10 items-center justify-center rounded-xl border border-miko-carrot/30 bg-white text-miko-olive transition-all duration-300 hover:-translate-y-1 hover:border-miko-rust hover:bg-miko-rust hover:text-white hover:shadow-md"
                    aria-label="اینستاگرام"
                  >
                    <div className="w-4 h-4 transition-transform group-hover:scale-110">
                      <SiteImage
                        imageKey="icon_instagram"
                        fallback=""
                        alt=""
                        className="w-full h-full object-contain"
                        placeholderContent={<InstagramIcon />}
                        showPlaceholder={true}
                      />
                    </div>
                  </a>
                  <a
                    href="https://t.me/afisup"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="group flex h-10 w-10 items-center justify-center rounded-xl border border-miko-carrot/30 bg-white text-miko-olive transition-all duration-300 hover:-translate-y-1 hover:border-miko-rust hover:bg-miko-rust hover:text-white hover:shadow-md"
                    aria-label="تلگرام"
                  >
                    <div className="w-4 h-4 transition-transform group-hover:scale-110">
                      <SiteImage
                        imageKey="icon_telegram"
                        fallback=""
                        alt=""
                        className="w-full h-full object-contain"
                        placeholderContent={<TelegramIcon />}
                        showPlaceholder={true}
                      />
                    </div>
                  </a>
                </div>
              </div>

              {/* ۲. لینک‌ها (۴ ستون) */}
              <div className="md:col-span-4 grid grid-cols-2 gap-4">
                <div>
                  <h4 className="mb-4 font-display text-sm font-black text-miko-rust flex items-center gap-1.5">
                    دسترسی سریع
                  </h4>
                  <ul className="space-y-3">
                    {QUICK_LINKS.map((link, idx) => (
                      <li key={idx}>
                        <Link
                          to={link.href}
                          onClick={(e) => handleNavClick(e, link.href)}
                          className="inline-block text-[13px] font-bold text-miko-dark/70 transition-all duration-200 hover:-translate-x-1 hover:text-miko-rust"
                        >
                          {link.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
                <div>
                  <h4 className="mb-4 font-display text-sm font-black text-miko-rust flex items-center gap-1.5">
                    پشتیبانی
                  </h4>
                  <ul className="space-y-3">
                    {SUPPORT_LINKS.map((link, idx) => (
                      <li key={idx}>
                        <Link
                          to={link.href}
                          className="inline-block text-[13px] font-bold text-miko-dark/70 transition-all duration-200 hover:-translate-x-1 hover:text-miko-rust"
                        >
                          {link.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              {/* ۳. تماس (۳ ستون) */}
              <div className="md:col-span-3">
                <h4 className="mb-4 font-display text-sm font-black text-miko-rust">
                  تماس با ما
                </h4>
                <ul className="space-y-3">
                  <li>
                    <a
                      href={PHONE_HREF}
                      className="group flex items-center gap-3 text-sm font-bold text-miko-dark/80 hover:text-miko-rust transition-colors"
                    >
                      <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-white border border-miko-carrot/30 text-miko-carrot group-hover:border-miko-rust group-hover:text-miko-rust group-hover:shadow-sm transition-all">
                        <div className="w-4 h-4">
                          <SiteImage
                            imageKey="icon_phone"
                            fallback=""
                            alt=""
                            className="w-full h-full object-contain"
                            placeholderContent={<PhoneIcon />}
                            showPlaceholder={true}
                          />
                        </div>
                      </div>
                      {/* ✅ شماره موبایل با اعداد فارسی (هاردکد، بدون toFa) */}
                      <span
                        dir="rtl"
                        lang="fa"
                        className="font-num text-[13px] tracking-normal whitespace-nowrap"
                      >
                        {PHONE_DISPLAY}
                      </span>
                    </a>
                  </li>
                </ul>
              </div>
            </div>

            {/* پایین فوتر */}
            <div className="mt-8 flex flex-col sm:flex-row items-center justify-between gap-4 border-t border-miko-carrot/20 pt-6">
              <p className="text-[11px] font-bold text-miko-dark/60">
                © {persianYear} میکو — تمامی حقوق محفوظ است.
              </p>
              <div className="flex items-center gap-2">
                {['NRC 2006', 'AAFCO 2024'].map((item) => (
                  <span
                    key={item}
                    className="rounded-lg border border-miko-olive/20 bg-white/60 px-2.5 py-1 text-[10px] font-black text-miko-olive"
                    dir="ltr"
                  >
                    {item}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </footer>
  );
}