// ============================================================
//  🧭 اعتبارسنجی آدرس تحویل — فایل سبک (بدون Leaflet)
//
//  چرا این فایل جدا است؟
//    UserApp.jsx و Cart.jsx و OrderDetail.jsx فقط به تابع
//    isDeliveryValid نیاز دارند؛ اگر آن را از DeliveryLocationPicker
//    ایمپورت کنند، کل کتابخانه‌ی Leaflet (~۲۰۰KB) وارد main.js می‌شود.
//
//  ⚠️ منطق این تابع عیناً کپی نسخه‌ی داخل DeliveryLocationPicker.jsx است.
//     اگر روزی نسخه‌ی داخل کامپوننت تغییر کرد، اینجا هم به‌روز کن
//     (یا کامپوننت را به import از همین فایل منتقل کن).
// ============================================================

export function isDeliveryValid(delivery) {
  if (!delivery) return false;
  const { city, address, lat, lng } = delivery;
  if (!city || !address || lat == null || lng == null) return false;
  if (typeof address !== 'string' || address.trim().length < 3) return false;
  if (!Number.isFinite(Number(lat)) || !Number.isFinite(Number(lng))) return false;
  if (Number(lat) < -90 || Number(lat) > 90) return false;
  if (Number(lng) < -180 || Number(lng) > 180) return false;
  return true;
}
